mapper.select:
SELECT pref_val, mod_dttm
FROM TB_SY_USER_PREF
WHERE user_id = 'admin' AND pref_type_cd = #{type} AND pref_key = #{key}

mapper.update:
UPDATE TB_SY_USER_PREF
SET pref_val = #{value}, mod_user_id = 'admin',
    mod_dttm = GREATEST(clock_timestamp() AT TIME ZONE 'UTC', mod_dttm + INTERVAL '1 microsecond')
WHERE user_id = 'admin' AND pref_type_cd = #{type} AND pref_key = #{key}
  AND mod_dttm IS NOT DISTINCT FROM #{token,jdbcType=TIMESTAMP}
